package com.musicplayer.data.local.filemanager

import android.content.Context
import android.os.Environment
import androidx.documentfile.provider.DocumentFile
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File
import javax.inject.Inject
import javax.inject.Singleton

data class FileItem(
    val name: String,
    val path: String,
    val isDirectory: Boolean,
    val size: Long,
    val lastModified: Long,
    val mimeType: String?,
    val isAudioFile: Boolean,
)

@Singleton
class FileManager @Inject constructor(
    @ApplicationContext private val context: Context,
) {
    private val audioExtensions = setOf(
        "mp3", "flac", "wav", "m4a", "ogg", "opus", "aac", "wma", "alac",
        "ape", "dsf", "dff", "aif", "aiff", "mka",
    )

    fun getRootPath(): String = Environment.getExternalStorageDirectory().absolutePath

    suspend fun listDirectory(path: String): List<FileItem> = withContext(Dispatchers.IO) {
        val dir = File(path)
        if (!dir.exists() || !dir.isDirectory) return@withContext emptyList()

        dir.listFiles()
            ?.sortedWith(compareBy({ !it.isDirectory }, { it.name.lowercase() }))
            ?.map { file ->
                val ext = file.extension.lowercase()
                FileItem(
                    name = file.name,
                    path = file.absolutePath,
                    isDirectory = file.isDirectory,
                    size = if (file.isFile) file.length() else 0L,
                    lastModified = file.lastModified(),
                    mimeType = if (file.isFile) getMimeType(ext) else null,
                    isAudioFile = ext in audioExtensions,
                )
            } ?: emptyList()
    }

    suspend fun renameFile(path: String, newName: String): Result<String> = withContext(Dispatchers.IO) {
        runCatching {
            val file = File(path)
            val newFile = File(file.parent, newName)
            if (file.renameTo(newFile)) newFile.absolutePath
            else throw Exception("Rename failed")
        }
    }

    suspend fun deleteFile(path: String): Result<Unit> = withContext(Dispatchers.IO) {
        runCatching {
            val file = File(path)
            if (!file.deleteRecursively()) throw Exception("Delete failed")
        }
    }

    suspend fun createDirectory(parentPath: String, name: String): Result<String> = withContext(Dispatchers.IO) {
        runCatching {
            val dir = File(parentPath, name)
            if (!dir.mkdirs()) throw Exception("Failed to create directory")
            dir.absolutePath
        }
    }

    suspend fun copyFile(sourcePath: String, destDirPath: String): Result<String> = withContext(Dispatchers.IO) {
        runCatching {
            val source = File(sourcePath)
            val destDir = File(destDirPath)
            val dest = File(destDir, source.name)
            source.copyTo(dest, overwrite = false)
            dest.absolutePath
        }
    }

    suspend fun moveFile(sourcePath: String, destDirPath: String): Result<String> = withContext(Dispatchers.IO) {
        runCatching {
            val source = File(sourcePath)
            val destDir = File(destDirPath)
            val dest = File(destDir, source.name)
            source.copyTo(dest, overwrite = false)
            source.delete()
            dest.absolutePath
        }
    }

    private fun getMimeType(extension: String): String = when (extension) {
        "mp3" -> "audio/mpeg"
        "flac" -> "audio/flac"
        "wav" -> "audio/wav"
        "m4a" -> "audio/mp4"
        "ogg" -> "audio/ogg"
        "opus" -> "audio/opus"
        "aac" -> "audio/aac"
        "wma" -> "audio/x-ms-wma"
        "ape" -> "audio/x-ape"
        "dsf" -> "audio/dsf"
        "dff" -> "audio/dff"
        "aif", "aiff" -> "audio/aiff"
        "mka" -> "audio/x-matroska"
        else -> "application/octet-stream"
    }
}

package com.musicplayer.data.repository

import com.musicplayer.data.local.db.dao.*
import com.musicplayer.data.local.mediastore.MediaStoreScanner
import com.musicplayer.domain.model.*
import kotlinx.coroutines.flow.Flow
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class MusicRepository @Inject constructor(
    private val trackDao: TrackDao,
    private val albumDao: AlbumDao,
    private val artistDao: ArtistDao,
    private val playlistDao: PlaylistDao,
    private val eqPresetDao: EqPresetDao,
    private val scanner: MediaStoreScanner,
) {
    // ---- Tracks ----
    fun getAllTracks(): Flow<List<Track>> = trackDao.getAllTracks()
    fun getTracksByAlbum(albumId: Long): Flow<List<Track>> = trackDao.getTracksByAlbum(albumId)
    fun getTracksByArtist(artistId: Long): Flow<List<Track>> = trackDao.getTracksByArtist(artistId)
    fun searchTracks(query: String): Flow<List<Track>> = trackDao.searchTracks(query)
    fun getFavoriteTracks(): Flow<List<Track>> = trackDao.getFavoriteTracks()
    fun getRecentlyPlayed(): Flow<List<Track>> = trackDao.getRecentlyPlayed()
    fun getRecentlyAdded(): Flow<List<Track>> = trackDao.getRecentlyAdded()
    suspend fun getTrackById(id: Long): Track? = trackDao.getTrackById(id)
    suspend fun setFavorite(id: Long, isFavorite: Boolean) = trackDao.setFavorite(id, isFavorite)
    suspend fun incrementPlayCount(id: Long) = trackDao.incrementPlayCount(id)

    // ---- Albums ----
    fun getAllAlbums(): Flow<List<Album>> = albumDao.getAllAlbums()
    fun getAlbumsByArtist(artistId: Long): Flow<List<Album>> = albumDao.getAlbumsByArtist(artistId)
    suspend fun getAlbumById(id: Long): Album? = albumDao.getAlbumById(id)

    // ---- Artists ----
    fun getAllArtists(): Flow<List<Artist>> = artistDao.getAllArtists()
    suspend fun getArtistById(id: Long): Artist? = artistDao.getArtistById(id)

    // ---- Playlists ----
    fun getAllPlaylists(): Flow<List<Playlist>> = playlistDao.getAllPlaylists()
    suspend fun getPlaylistById(id: Long): Playlist? = playlistDao.getPlaylistById(id)
    suspend fun createPlaylist(playlist: Playlist): Long = playlistDao.insertPlaylist(playlist)
    suspend fun updatePlaylist(playlist: Playlist) = playlistDao.updatePlaylist(playlist)
    suspend fun deletePlaylist(id: Long) = playlistDao.deletePlaylistById(id)

    // ---- EQ Presets ----
    fun getAllEqPresets(): Flow<List<EqPreset>> = eqPresetDao.getAllPresets()
    suspend fun getEqPresetById(id: Long): EqPreset? = eqPresetDao.getPresetById(id)
    suspend fun saveEqPreset(preset: EqPreset): Long = eqPresetDao.insertPreset(preset)
    suspend fun deleteEqPreset(id: Long) = eqPresetDao.deleteUserPreset(id)

    // ---- Library Scan ----
    suspend fun scanLibrary() {
        val result = scanner.scan()
        trackDao.upsertTracks(result.tracks)
        albumDao.upsertAlbums(result.albums)
        artistDao.upsertArtists(result.artists)
        // Remove stale entries
        val activeTrackIds = result.tracks.map { it.id }
        val activeAlbumIds = result.albums.map { it.id }
        val activeArtistIds = result.artists.map { it.id }
        if (activeTrackIds.isNotEmpty()) trackDao.deleteRemovedTracks(activeTrackIds)
        if (activeAlbumIds.isNotEmpty()) albumDao.deleteRemovedAlbums(activeAlbumIds)
        if (activeArtistIds.isNotEmpty()) artistDao.deleteRemovedArtists(activeArtistIds)
    }
}

package com.musicplayer.util

import kotlin.math.pow

/**
 * Maps a UI volume level (1–50) to a linear gain factor (0.0–1.0).
 *
 * Uses a logarithmic curve so that each level step sounds perceptually equal.
 * Level 50 = 0 dB (full gain = 1.0)
 * Level 1  = -40 dB (gain ≈ 0.01 — barely audible)
 *
 * Formula: gain = 10 ^ ((level - 50) × 40 / (50 × 20))
 *        = 10 ^ ((level - 50) × 0.04)
 */
object VolumeUtil {
    const val MIN_LEVEL = 1
    const val MAX_LEVEL = 50

    /** Convert UI level (1–50) to ExoPlayer gain (0.0–1.0). */
    fun levelToGain(level: Int): Float {
        val clamped = level.coerceIn(MIN_LEVEL, MAX_LEVEL)
        return 10f.pow((clamped - MAX_LEVEL) * 0.04f)
    }

    /** Convert ExoPlayer gain (0.0–1.0) back to the nearest UI level (1–50). */
    fun gainToLevel(gain: Float): Int {
        if (gain <= 0f) return MIN_LEVEL
        val level = (MAX_LEVEL + Math.log10(gain.toDouble()) / 0.04).toInt()
        return level.coerceIn(MIN_LEVEL, MAX_LEVEL)
    }

    /** Human-readable dB string for the given level, e.g. "-12.0 dB". */
    fun levelToDbString(level: Int): String {
        val db = (level - MAX_LEVEL) * 0.04 * 20
        return if (level == MAX_LEVEL) "0 dB" else "${"%.1f".format(db)} dB"
    }
}

package com.musicplayer.util

/**
 * Helpers for displaying audio format information on the Now Playing screen.
 */
object AudioFormatUtil {

    /** Returns a compact badge string, e.g. "FLAC 24-bit / 96 kHz" */
    fun formatBadge(mimeType: String, sampleRate: Int, bitDepth: Int, bitrate: Int): String {
        val format = mimeTypeToFormat(mimeType)
        val rate = sampleRateLabel(sampleRate)
        val depth = if (bitDepth > 0 && bitDepth != 16) "$bitDepth-bit" else ""
        val bitrateStr = if (bitrate > 0 && isLossyFormat(mimeType)) "${bitrate}k" else ""

        return buildString {
            append(format)
            if (depth.isNotEmpty()) append(" $depth")
            if (rate.isNotEmpty()) append(" / $rate")
            if (bitrateStr.isNotEmpty()) append(" $bitrateStr")
        }.trim()
    }

    fun mimeTypeToFormat(mimeType: String): String = when {
        mimeType.contains("flac") -> "FLAC"
        mimeType.contains("wav") || mimeType.contains("wave") -> "WAV"
        mimeType.contains("mp4") || mimeType.contains("m4a") || mimeType.contains("aac") -> "AAC"
        mimeType.contains("mpeg") || mimeType.contains("mp3") -> "MP3"
        mimeType.contains("ogg") -> "OGG"
        mimeType.contains("opus") -> "OPUS"
        mimeType.contains("wma") -> "WMA"
        mimeType.contains("ape") -> "APE"
        mimeType.contains("dsf") || mimeType.contains("dff") -> "DSD"
        mimeType.contains("aiff") || mimeType.contains("aif") -> "AIFF"
        mimeType.contains("alac") -> "ALAC"
        mimeType.contains("matroska") || mimeType.contains("mka") -> "MKA"
        else -> mimeType.substringAfterLast("/").uppercase()
    }

    fun sampleRateLabel(sampleRateHz: Int): String = when {
        sampleRateHz <= 0 -> ""
        sampleRateHz >= 1000 -> "${"%.0f".format(sampleRateHz / 1000.0)} kHz"
        else -> "$sampleRateHz Hz"
    }

    fun isLossyFormat(mimeType: String): Boolean =
        mimeType.contains("mp3") || mimeType.contains("mpeg") ||
        mimeType.contains("aac") || mimeType.contains("ogg") ||
        mimeType.contains("opus") || mimeType.contains("wma")

    /** Returns true if the format is hi-res (>16-bit or >48kHz). */
    fun isHiRes(sampleRate: Int, bitDepth: Int): Boolean =
        sampleRate > 48000 || bitDepth > 16
}

package com.musicplayer.util

object TimeUtil {
    /** Format milliseconds as M:SS or H:MM:SS */
    fun formatDuration(millis: Long): String {
        val totalSeconds = millis / 1000
        val hours = totalSeconds / 3600
        val minutes = (totalSeconds % 3600) / 60
        val seconds = totalSeconds % 60
        return if (hours > 0) {
            "%d:%02d:%02d".format(hours, minutes, seconds)
        } else {
            "%d:%02d".format(minutes, seconds)
        }
    }

    /** Format file size as human-readable string */
    fun formatFileSize(bytes: Long): String = when {
        bytes >= 1_073_741_824 -> "${"%.1f".format(bytes / 1_073_741_824.0)} GB"
        bytes >= 1_048_576 -> "${"%.1f".format(bytes / 1_048_576.0)} MB"
        bytes >= 1024 -> "${"%.0f".format(bytes / 1024.0)} KB"
        else -> "$bytes B"
    }
}

package com.musicplayer.service

import android.app.PendingIntent
import android.content.Intent
import android.media.audiofx.BassBoost
import android.media.audiofx.Equalizer
import android.media.audiofx.LoudnessEnhancer
import android.media.audiofx.Virtualizer
import androidx.media3.common.AudioAttributes
import androidx.media3.common.C
import androidx.media3.common.Player
import androidx.media3.exoplayer.ExoPlayer
import androidx.media3.session.MediaSession
import androidx.media3.session.MediaSessionService
import com.musicplayer.MainActivity
import com.musicplayer.util.VolumeUtil
import dagger.hilt.android.AndroidEntryPoint
import javax.inject.Inject

/**
 * Foreground service that hosts ExoPlayer and the MediaSession.
 * Audio effects (EQ, BassBoost, Virtualizer, LoudnessEnhancer) are attached here
 * to the audio session ID immediately after ExoPlayer is initialized.
 */
@AndroidEntryPoint
class MusicPlayerService : MediaSessionService() {

    private var mediaSession: MediaSession? = null
    private var player: ExoPlayer? = null

    // Audio effects — created once we have a valid audio session ID
    var equalizer: Equalizer? = null
        private set
    var bassBoost: BassBoost? = null
        private set
    var virtualizer: Virtualizer? = null
        private set
    var loudnessEnhancer: LoudnessEnhancer? = null
        private set

    override fun onCreate() {
        super.onCreate()
        initPlayer()
    }

    private fun initPlayer() {
        val audioAttributes = AudioAttributes.Builder()
            .setUsage(C.USAGE_MEDIA)
            .setContentType(C.AUDIO_CONTENT_TYPE_MUSIC)
            .build()

        val exoPlayer = ExoPlayer.Builder(this)
            .setAudioAttributes(audioAttributes, /* handleAudioFocus = */ true)
            .setHandleAudioBecomingNoisy(true)  // pause on headphone unplug
            .build()

        player = exoPlayer

        // Attach audio effects once session ID is available
        exoPlayer.addListener(object : Player.Listener {
            override fun onPlaybackStateChanged(playbackState: Int) {
                if (playbackState == Player.STATE_READY && equalizer == null) {
                    attachAudioEffects(exoPlayer.audioSessionId)
                }
            }
        })

        val sessionActivityIntent = PendingIntent.getActivity(
            this, 0,
            Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE,
        )

        mediaSession = MediaSession.Builder(this, exoPlayer)
            .setSessionActivity(sessionActivityIntent)
            .build()
    }

    private fun attachAudioEffects(audioSessionId: Int) {
        if (audioSessionId == 0) return
        try {
            equalizer = Equalizer(0, audioSessionId).apply { enabled = true }
            bassBoost = BassBoost(0, audioSessionId).apply { enabled = true }
            virtualizer = Virtualizer(0, audioSessionId).apply { enabled = true }
            loudnessEnhancer = LoudnessEnhancer(audioSessionId).apply { enabled = true }
        } catch (e: Exception) {
            // Some devices throw on effect creation — handle gracefully
        }
    }

    fun setVolume(level: Int) {
        player?.volume = VolumeUtil.levelToGain(level)
    }

    override fun onGetSession(controllerInfo: MediaSession.ControllerInfo): MediaSession? =
        mediaSession

    override fun onDestroy() {
        mediaSession?.run {
            player.release()
            release()
            mediaSession = null
        }
        equalizer?.release()
        bassBoost?.release()
        virtualizer?.release()
        loudnessEnhancer?.release()
        super.onDestroy()
    }
}

