@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun LibraryScreen(
    navController: NavController,
    viewModel: LibraryViewModel = hiltViewModel(),
) {
    val state by viewModel.uiState.collectAsStateWithLifecycle()
    val tabs = LibraryTab.entries

    Scaffold(
        topBar = {
            Column {
                TopAppBar(title = { Text("Library") })
                // Search bar
                OutlinedTextField(
                    value = state.searchQuery,
                    onValueChange = viewModel::setSearchQuery,
                    placeholder = { Text("Search tracks, albums, artists…") },
                    leadingIcon = { Icon(Icons.Default.Search, null) },
                    singleLine = true,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 4.dp),
                )
                // Tab row
                ScrollableTabRow(selectedTabIndex = tabs.indexOf(state.selectedTab)) {
                    tabs.forEach { tab ->
                        Tab(
                            selected = state.selectedTab == tab,
                            onClick = { viewModel.selectTab(tab) },
                            text = { Text(tab.name) },
                        )
                    }
                }
            }
        },
    ) { padding ->
        Box(modifier = Modifier.fillMaxSize().padding(padding)) {
            when (state.selectedTab) {
                LibraryTab.Tracks -> LazyColumn {
                    items(state.tracks) { track ->
                        TrackListItem(
                            track = track,
                            onClick = { /* TODO: play */ },
                            onFavoriteToggle = { viewModel.toggleFavorite(track.id, track.isFavorite) },
                        )
                    }
                }
                LibraryTab.Albums -> LazyVerticalGrid(
                    columns = GridCells.Adaptive(160.dp),
                    contentPadding = PaddingValues(8.dp),
                ) {
                    items(state.albums) { album ->
                        AlbumCard(
                            album = album,
                            onClick = { navController.navigate(Screen.AlbumDetail.createRoute(album.id)) },
                        )
                    }
                }
                LibraryTab.Artists -> LazyColumn {
                    items(state.artists) { artist ->
                        ListItem(
                            headlineContent = { Text(artist.name) },
                            supportingContent = { Text("${artist.albumCount} albums · ${artist.trackCount} tracks") },
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp)
                        )
                        HorizontalDivider()
                    }
                }
                LibraryTab.Playlists -> LazyColumn {
                    items(state.playlists) { playlist ->
                        ListItem(
                            headlineContent = { Text(playlist.name) },
                            supportingContent = { Text(playlist.description) },
                        )
                        HorizontalDivider()
                    }
                }
            }
        }
    }
}

package com.musicplayer.ui.screens.nowplaying

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.musicplayer.data.repository.MusicRepository
import com.musicplayer.domain.model.Track
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject

data class NowPlayingUiState(
    val currentTrack: Track? = null,
    val isPlaying: Boolean = false,
    val volumeLevel: Int = 35,        // 1–50
    val progressMs: Long = 0L,
    val durationMs: Long = 0L,
    val isShuffled: Boolean = false,
    val repeatMode: Int = 0,          // 0=off, 1=one, 2=all
    val isFavorite: Boolean = false,
)

@HiltViewModel
class NowPlayingViewModel @Inject constructor(
    private val repo: MusicRepository,
) : ViewModel() {

    private val _state = MutableStateFlow(NowPlayingUiState())
    val uiState: StateFlow<NowPlayingUiState> = _state.asStateFlow()

    fun setVolumeLevel(level: Int) {
        _state.update { it.copy(volumeLevel = level) }
        // TODO: forward to MusicPlayerService via binder or event bus
    }

    fun toggleFavorite() = viewModelScope.launch {
        val track = _state.value.currentTrack ?: return@launch
        repo.setFavorite(track.id, !track.isFavorite)
        _state.update { it.copy(isFavorite = !it.isFavorite) }
    }

    fun seekTo(positionMs: Long) {
        // TODO: forward to ExoPlayer via service connection
        _state.update { it.copy(progressMs = positionMs) }
    }

    fun toggleShuffle() { _state.update { it.copy(isShuffled = !it.isShuffled) } }
    fun cycleRepeat() { _state.update { it.copy(repeatMode = (it.repeatMode + 1) % 3) } }
}

