                title = {},
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(Icons.Default.KeyboardArrowDown, "Collapse")
                    }
                },
                actions = {
                    IconButton(onClick = { navController.navigate(Screen.Equalizer.route) }) {
                        Icon(Icons.Default.Equalizer, "Equalizer")
                    }
                    IconButton(onClick = { /* TODO: sleep timer */ }) {
                        Icon(Icons.Default.Timer, "Sleep timer")
                    }
                },
            )
        },
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Spacer(Modifier.height(16.dp))

            // Album art
