                shape = MaterialTheme.shapes.large,
                tonalElevation = 4.dp,
                modifier = Modifier
                    .fillMaxWidth()
                    .aspectRatio(1f)
                    .clip(MaterialTheme.shapes.large),
            ) {
                AsyncImage(
                    model = if (track != null) "content://media/external/audio/albumart/${track.albumId}" else null,
                    contentDescription = "Album art",
                    contentScale = ContentScale.Crop,
                    modifier = Modifier.fillMaxSize(),
                )
            }

            Spacer(Modifier.height(24.dp))

            // Track info row
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(Modifier.weight(1f)) {
                    Text(
                        text = track?.title ?: "No track selected",
                        style = MaterialTheme.typography.headlineMedium,
                        maxLines = 1,
                    )
                    Text(
                        text = track?.artist ?: "",
                        style = MaterialTheme.typography.bodyLarge,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                    // Format badge
                    if (track != null) {
                        Text(
                            text = AudioFormatUtil.formatBadge(
                                track.mimeType, track.sampleRate, track.bitDepth, track.bitrate
                            ),
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                        )
                    }
                }
                IconButton(onClick = { viewModel.toggleFavorite() }) {
                    Icon(
                        imageVector = if (state.isFavorite) Icons.Default.Favorite else Icons.Default.FavoriteBorder,
                        contentDescription = "Favorite",
                        tint = if (state.isFavorite) MaterialTheme.colorScheme.primary
                        else MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }

            Spacer(Modifier.height(16.dp))

            // Seek bar
            val progress = if (state.durationMs > 0) state.progressMs.toFloat() / state.durationMs else 0f
            Slider(
                value = progress,
                onValueChange = { viewModel.seekTo((it * state.durationMs).toLong()) },
                modifier = Modifier.fillMaxWidth(),
            )
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text(TimeUtil.formatDuration(state.progressMs), style = MaterialTheme.typography.bodySmall)
                Text(TimeUtil.formatDuration(state.durationMs), style = MaterialTheme.typography.bodySmall)
            }

            Spacer(Modifier.height(16.dp))

            // Transport controls
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                IconButton(onClick = { viewModel.toggleShuffle() }) {
                    Icon(
                        imageVector = Icons.Default.Shuffle,
                        contentDescription = "Shuffle",
                        tint = if (state.isShuffled) MaterialTheme.colorScheme.primary
                        else MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                IconButton(onClick = { /* TODO: previous */ }, modifier = Modifier.size(56.dp)) {
                    Icon(Icons.Default.SkipPrevious, "Previous", modifier = Modifier.size(36.dp))
                }
                FilledIconButton(
                    onClick = { /* TODO: play/pause */ },
                    modifier = Modifier.size(64.dp),
                ) {
                    Icon(
                        imageVector = if (state.isPlaying) Icons.Default.Pause else Icons.Default.PlayArrow,
                        contentDescription = if (state.isPlaying) "Pause" else "Play",
                        modifier = Modifier.size(40.dp),
                    )
                }
                IconButton(onClick = { /* TODO: next */ }, modifier = Modifier.size(56.dp)) {
                    Icon(Icons.Default.SkipNext, "Next", modifier = Modifier.size(36.dp))
                }
                IconButton(onClick = { viewModel.cycleRepeat() }) {
                    Icon(
                        imageVector = when (state.repeatMode) {
                            1 -> Icons.Default.RepeatOne
                            2 -> Icons.Default.Repeat
                            else -> Icons.Default.Repeat
                        },
                        contentDescription = "Repeat",
                        tint = if (state.repeatMode > 0) MaterialTheme.colorScheme.primary
                        else MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }

            Spacer(Modifier.height(24.dp))

            // Volume control
            VolumeSlider(
                level = state.volumeLevel,
                onLevelChange = viewModel::setVolumeLevel,
                modifier = Modifier.fillMaxWidth(),
            )
        }
    }
}

package com.musicplayer.ui.screens.equalizer

import android.media.audiofx.Equalizer
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.musicplayer.data.repository.MusicRepository
import com.musicplayer.domain.model.EqPreset
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject

data class BandState(
    val index: Int,
    val frequencyHz: Int,
    val gainMillibel: Int,
    val minMillibel: Int,
    val maxMillibel: Int,
)

data class EqualizerUiState(
    val isEnabled: Boolean = true,
    val bands: List<BandState> = emptyList(),
    val bassBoostStrength: Int = 0,       // 0–1000
    val virtualizerStrength: Int = 0,     // 0–1000
    val loudnessGainMb: Int = 0,
    val presets: List<EqPreset> = emptyList(),
    val selectedPresetId: Long? = null,
)

@HiltViewModel
class EqualizerViewModel @Inject constructor(
    private val repo: MusicRepository,
) : ViewModel() {

    private val _state = MutableStateFlow(EqualizerUiState())
    val uiState: StateFlow<EqualizerUiState> = _state.asStateFlow()

    init {
        viewModelScope.launch {
            repo.getAllEqPresets().collect { presets ->
                _state.update { it.copy(presets = presets) }
            }
        }
    }

    /**
     * Must be called after service connection is established and Equalizer is available.
     * Reads the hardware band configuration from the device.
     */
    fun initFromHardware(equalizer: Equalizer) {
        val numBands = equalizer.numberOfBands.toInt()
        val bands = (0 until numBands).map { i ->
            val freqRange = equalizer.getBandFreqRange(i.toShort())
            val centerFreq = freqRange?.let { (it[0] + it[1]) / 2 } ?: 0
            BandState(
                index = i,
                frequencyHz = centerFreq / 1000, // milliHz → Hz
                gainMillibel = equalizer.getBandLevel(i.toShort()).toInt(),
                minMillibel = equalizer.bandLevelRange?.get(0)?.toInt() ?: -1500,
                maxMillibel = equalizer.bandLevelRange?.get(1)?.toInt() ?: 1500,
            )
        }
        _state.update { it.copy(bands = bands) }
    }

    fun setBandGain(bandIndex: Int, gainMillibel: Int) {
        val updated = _state.value.bands.toMutableList()
        if (bandIndex in updated.indices) {
            updated[bandIndex] = updated[bandIndex].copy(gainMillibel = gainMillibel)
            _state.update { it.copy(bands = updated, selectedPresetId = null) }
            // TODO: forward to service → equalizer.setBandLevel(...)
        }
    }

    fun setBassBoost(strength: Int) {
        _state.update { it.copy(bassBoostStrength = strength) }
        // TODO: forward to service → bassBoost.setStrength(...)
    }

    fun setVirtualizer(strength: Int) {
        _state.update { it.copy(virtualizerStrength = strength) }
    }

    fun setLoudnessGain(gainMb: Int) {
        _state.update { it.copy(loudnessGainMb = gainMb) }
    }

    fun toggleEnabled() {
        _state.update { it.copy(isEnabled = !it.isEnabled) }
    }

    fun applyPreset(preset: EqPreset) {
        // Parse band gains from JSON string "[val, val, ...]"
        val gains = preset.bandGains
            .removePrefix("[").removeSuffix("]")
            .split(",")
            .mapNotNull { it.trim().toIntOrNull() }
        val updatedBands = _state.value.bands.mapIndexed { i, band ->
            band.copy(gainMillibel = gains.getOrElse(i) { 0 })
        }
        _state.update {
            it.copy(
                bands = updatedBands,
                bassBoostStrength = preset.bassBoostStrength,
                virtualizerStrength = preset.virtualizerStrength,
                loudnessGainMb = preset.loudnessGainMb,
                selectedPresetId = preset.id,
            )
        }
    }

    fun saveCurrentAsPreset(name: String) = viewModelScope.launch {
        val gains = "[" + _state.value.bands.joinToString(",") { it.gainMillibel.toString() } + "]"
        val preset = EqPreset(
            name = name,
            bandGains = gains,
            bassBoostStrength = _state.value.bassBoostStrength,
            virtualizerStrength = _state.value.virtualizerStrength,
            loudnessGainMb = _state.value.loudnessGainMb,
        )
        repo.saveEqPreset(preset)
    }
}

package com.musicplayer.ui.screens.equalizer

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.LazyRow
