@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EqualizerScreen(
    navController: NavController,
    viewModel: EqualizerViewModel = hiltViewModel(),
) {
    val state by viewModel.uiState.collectAsStateWithLifecycle()
    var showSaveDialog by remember { mutableStateOf(false) }
    var presetName by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Equalizer") },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(Icons.Default.ArrowBack, "Back")
                    }
                },
                actions = {
                    // EQ on/off toggle
                    Switch(
                        checked = state.isEnabled,
                        onCheckedChange = { viewModel.toggleEnabled() },
                    )
                    IconButton(onClick = { showSaveDialog = true }) {
                        Icon(Icons.Default.Add, "Save preset")
                    }
                },
            )
        },
    ) { padding ->
        LazyColumn(
            modifier = Modifier.fillMaxSize().padding(padding).padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            // Preset chips
            item {
                Text("Presets", style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(vertical = 8.dp))
                LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    items(state.presets) { preset ->
                        FilterChip(
                            selected = state.selectedPresetId == preset.id,
                            onClick = { viewModel.applyPreset(preset) },
                            label = { Text(preset.name) },
                        )
                    }
                }
            }

            // Per-band sliders
            item {
                Text(
                    "Frequency Bands",
                    style = MaterialTheme.typography.titleMedium,
                    modifier = Modifier.padding(vertical = 8.dp),
                )
            }
            items(state.bands) { band ->
                Column(modifier = Modifier.fillMaxWidth()) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                    ) {
                        Text(
                            text = if (band.frequencyHz >= 1000) "${band.frequencyHz / 1000} kHz"
                            else "${band.frequencyHz} Hz",
                            style = MaterialTheme.typography.bodySmall,
                        )
                        Text(
                            text = "${"%.1f".format(band.gainMillibel / 100.0)} dB",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.primary,
                        )
                    }
                    Slider(
                        value = band.gainMillibel.toFloat(),
                        onValueChange = { viewModel.setBandGain(band.index, it.toInt()) },
                        valueRange = band.minMillibel.toFloat()..band.maxMillibel.toFloat(),
                        enabled = state.isEnabled,
                        modifier = Modifier.fillMaxWidth(),
                    )
                }
            }

            // BassBoost
            item {
                Text("Bass Boost", style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(top = 12.dp))
                Slider(
                    value = state.bassBoostStrength.toFloat(),
                    onValueChange = { viewModel.setBassBoost(it.toInt()) },
                    valueRange = 0f..1000f,
                    enabled = state.isEnabled,
                    modifier = Modifier.fillMaxWidth(),
                )
                Text("Strength: ${state.bassBoostStrength}", style = MaterialTheme.typography.bodySmall)
            }

            // Virtualizer
            item {
                Text("Virtualizer (Headphones)", style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(top = 12.dp))
                Slider(
                    value = state.virtualizerStrength.toFloat(),
                    onValueChange = { viewModel.setVirtualizer(it.toInt()) },
                    valueRange = 0f..1000f,
                    enabled = state.isEnabled,
                    modifier = Modifier.fillMaxWidth(),
                )
            }

            // Loudness Enhancer
            item {
                Text("Loudness Enhancer", style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(top = 12.dp))
                Slider(
                    value = state.loudnessGainMb.toFloat(),
                    onValueChange = { viewModel.setLoudnessGain(it.toInt()) },
                    valueRange = 0f..1000f,
                    enabled = state.isEnabled,
                    modifier = Modifier.fillMaxWidth(),
                )
                Spacer(Modifier.height(24.dp))
            }
        }
    }

    if (showSaveDialog) {
        AlertDialog(
            onDismissRequest = { showSaveDialog = false },
            title = { Text("Save Preset") },
            text = {
                OutlinedTextField(
                    value = presetName,
                    onValueChange = { presetName = it },
                    label = { Text("Preset name") },
                    singleLine = true,
                )
            },
            confirmButton = {
                TextButton(onClick = {
                    if (presetName.isNotBlank()) {
                        viewModel.saveCurrentAsPreset(presetName)
                        showSaveDialog = false
                        presetName = ""
                    }
                }) { Text("Save") }
            },
            dismissButton = {
                TextButton(onClick = { showSaveDialog = false }) { Text("Cancel") }
            },
        )
    }
}

package com.musicplayer.ui.screens.fileexplorer

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.musicplayer.data.local.filemanager.FileItem
import com.musicplayer.data.repository.FileRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject

data class FileExplorerUiState(
    val currentPath: String = "",
    val items: List<FileItem> = emptyList(),
    val breadcrumbs: List<Pair<String, String>> = emptyList(), // label to path
    val isLoading: Boolean = false,
    val clipboardPath: String? = null,
    val clipboardIsCut: Boolean = false,
    val selectedPaths: Set<String> = emptySet(),
    val errorMessage: String? = null,
)

@HiltViewModel
class FileExplorerViewModel @Inject constructor(
    private val fileRepo: FileRepository,
) : ViewModel() {

    private val _state = MutableStateFlow(FileExplorerUiState())
    val uiState: StateFlow<FileExplorerUiState> = _state.asStateFlow()

    fun init(initialPath: String) {
        val startPath = initialPath.ifBlank { fileRepo.getRootPath() }
        navigateTo(startPath)
    }

    fun navigateTo(path: String) = viewModelScope.launch {
        _state.update { it.copy(isLoading = true, errorMessage = null) }
        val items = fileRepo.listDirectory(path)
        val breadcrumbs = buildBreadcrumbs(path)
        _state.update {
            it.copy(
                currentPath = path,
                items = items,
                breadcrumbs = breadcrumbs,
                isLoading = false,
                selectedPaths = emptySet(),
            )
        }
    }

    fun navigateUp() {
        val parent = java.io.File(_state.value.currentPath).parent ?: return
        navigateTo(parent)
    }

    fun toggleSelection(path: String) {
        val current = _state.value.selectedPaths.toMutableSet()
        if (path in current) current.remove(path) else current.add(path)
        _state.update { it.copy(selectedPaths = current) }
    }

    fun selectAll() {
        val all = _state.value.items.map { it.path }.toSet()
        _state.update { it.copy(selectedPaths = all) }
    }

    fun clearSelection() = _state.update { it.copy(selectedPaths = emptySet()) }

    fun cutSelected() {
        val selected = _state.value.selectedPaths.firstOrNull() ?: return
        _state.update { it.copy(clipboardPath = selected, clipboardIsCut = true) }
    }

    fun copySelected() {
        val selected = _state.value.selectedPaths.firstOrNull() ?: return
        _state.update { it.copy(clipboardPath = selected, clipboardIsCut = false) }
    }

    fun paste() = viewModelScope.launch {
        val sourcePath = _state.value.clipboardPath ?: return@launch
        val destDir = _state.value.currentPath
        val result = if (_state.value.clipboardIsCut)
            fileRepo.moveFile(sourcePath, destDir)
        else
            fileRepo.copyFile(sourcePath, destDir)
        result.onSuccess { _state.update { it.copy(clipboardPath = null) }; refresh() }
        result.onFailure { _state.update { it.copy(errorMessage = it.toString()) } }
    }

    fun rename(path: String, newName: String) = viewModelScope.launch {
        fileRepo.renameFile(path, newName)
            .onSuccess { refresh() }
            .onFailure { _state.update { it.copy(errorMessage = it.toString()) } }
    }

    fun delete(path: String) = viewModelScope.launch {
        fileRepo.deleteFile(path)
            .onSuccess { refresh() }
            .onFailure { _state.update { it.copy(errorMessage = it.toString()) } }
    }

    fun createFolder(name: String) = viewModelScope.launch {
        fileRepo.createDirectory(_state.value.currentPath, name)
            .onSuccess { refresh() }
            .onFailure { _state.update { it.copy(errorMessage = it.toString()) } }
    }

    fun refresh() { navigateTo(_state.value.currentPath) }

    private fun buildBreadcrumbs(path: String): List<Pair<String, String>> {
        val root = fileRepo.getRootPath()
        if (!path.startsWith(root)) return listOf("Storage" to path)
        val relative = path.removePrefix(root).trimStart('/', '\\')
        val parts = mutableListOf("Storage" to root)
        var current = root
        if (relative.isNotEmpty()) {
            relative.split("/", "\\").forEach { segment ->
                current = "$current/$segment"
                parts.add(segment to current)
            }
        }
        return parts
    }
}

